/**
 * Shared conversion utility for all unit categories
 * Extracted to follow DRY principle
 */

/**
 * Generic conversion function that works for any unit category
 */
export function convertUnit(units, from, to, value, precision = 5) {
  const fromUnit = units.fields.find((field) =>
    field.units.some((unit) => unit.key === from)
  );

  if (!fromUnit) return value;

  const toUnitField = units.fields.find((field) =>
    field.units.some((unit) => unit.key === to)
  );

  if (!toUnitField || fromUnit.field !== toUnitField.field) return value;

  const fromUnitData = fromUnit.units.find((unit) => unit.key === from);
  const toUnitData = toUnitField.units.find((unit) => unit.key === to);

  return parseFloat(
    (parseFloat(value) * (toUnitData.nm / fromUnitData.nm)).toFixed(precision)
  );
}
