import si from '@src/unitSystem';
import { convertUnit } from '@src/utils/conversion';

// Temperature unit constants
const TEMP_CELSIUS = 'C';
const TEMP_FAHRENHEIT = 'F';
const TEMP_KELVIN = 'K';

// Temperature conversion constants
const FAHRENHEIT_OFFSET = 32;
const FAHRENHEIT_RATIO = 1.8;
const KELVIN_OFFSET = 273.15;

export function genUnitsSystem(options = {}) {
  const { externalUnits = {} } = options;
  if (Object.keys(externalUnits).length >= 1) return externalUnits.fields || [];
  return si.fields;
}

export function convertTemperature(key, val) {
  switch (key) {
    case TEMP_FAHRENHEIT:
      return parseFloat(
        (parseFloat(val) * FAHRENHEIT_RATIO + FAHRENHEIT_OFFSET).toFixed(2)
      ); // convert from Celsius to Fahrenheit
    case TEMP_KELVIN:
      return parseFloat((((parseFloat(val) + 459.67) * 5) / 9).toFixed(2)); // convert from Fahrenheit to Kelvin
    case TEMP_CELSIUS:
      return parseFloat((parseFloat(val) - KELVIN_OFFSET).toFixed(2)); // convert from Kelvin to Celsius
    default:
      return parseFloat(val);
  }
}

/**
 * Universal conversion function
 * @example
 * convert('amount_substance', 42, 'mol', 'mmol') // Returns 42000
 * convert('length', 10, 'mm', 'cm') // Returns 1
 * convert('pressure', 1, 'atm', 'pa') // Returns 101325
 * convert('temperature', 0, 'C', 'F') // Returns 32
 */
export function convert(field, value, from, to, precision = 5) {
  // If the unit is not found, return the original value
  const fieldData = si.fields.find((f) => f.field === field);

  if (!fieldData) return value;

  // Handle temperature conversions separately
  if (field === 'temperature') {
    if (from === to) return parseFloat(value);

    const val = parseFloat(value);
    let celsiusValue = val;

    // Convert from source unit to Celsius
    if (from === TEMP_FAHRENHEIT) {
      celsiusValue = (val - FAHRENHEIT_OFFSET) / FAHRENHEIT_RATIO;
    } else if (from === TEMP_KELVIN) {
      celsiusValue = val - KELVIN_OFFSET;
    }
    // If from === TEMP_CELSIUS, celsiusValue is already correct

    // Convert from Celsius to target unit and apply precision
    if (to === TEMP_CELSIUS) {
      return parseFloat(celsiusValue.toFixed(precision));
    } else if (to === TEMP_FAHRENHEIT) {
      return parseFloat(
        (celsiusValue * FAHRENHEIT_RATIO + FAHRENHEIT_OFFSET).toFixed(precision)
      );
    } else if (to === TEMP_KELVIN) {
      return parseFloat((celsiusValue + KELVIN_OFFSET).toFixed(precision));
    }

    return val;
  }

  return convertUnit({ fields: [fieldData] }, from, to, value, precision);
}
