// Dev-only playground. Imports live source through the public entry so it
// mirrors the published API (and gets HMR via `yarn dev`). It is NOT part of
// the library build (lib mode entry = index.js) nor the published package
// (files: ["dist/*"]), so it has zero impact on bundle size.
import { convert, genUnitsSystem, getVersion } from '../index.js';

const fields = genUnitsSystem();

const $ = (id) => document.getElementById(id);
const fieldSel = $('field');
const fromSel = $('from');
const toSel = $('to');
const valInput = $('value');
const precInput = $('precision');
const resultEl = $('result');
const formulaEl = $('formula');

$('version').textContent = `v${getVersion()}`;

// Labels in units.json may contain HTML (e.g. "mA/cm<sup>2</sup>").
// <option> can't render HTML, so map <sup>…</sup> to unicode and strip the rest.
const SUP = {
  0: '⁰',
  1: '¹',
  2: '²',
  3: '³',
  4: '⁴',
  5: '⁵',
  6: '⁶',
  7: '⁷',
  8: '⁸',
  9: '⁹',
  '-': '⁻',
};
const pretty = (label) =>
  label
    .replace(/<sup>(.*?)<\/sup>/g, (_, s) =>
      [...s].map((c) => SUP[c] ?? c).join('')
    )
    .replace(/<[^>]+>/g, '');

const currentField = () => fields.find((f) => f.field === fieldSel.value);

// Sort by label for display only — copy first so we never mutate the live
// units.json arrays (their order is significant for unitConversion).
const byLabel = (a, b) => pretty(a.label).localeCompare(pretty(b.label));

function fillUnits(sel, units, index) {
  sel.innerHTML = '';
  [...units].sort(byLabel).forEach((u) => {
    const o = document.createElement('option');
    o.value = u.key;
    o.textContent = pretty(u.label);
    sel.appendChild(o);
  });
  sel.selectedIndex = index;
}

function compute() {
  const f = currentField();
  const val = parseFloat(valInput.value);
  const prec = parseInt(precInput.value, 10);
  if (Number.isNaN(val)) {
    resultEl.textContent = '—';
    formulaEl.textContent = '';
    return;
  }
  const precision = Number.isNaN(prec) ? 5 : prec;
  const out = convert(f.field, val, fromSel.value, toSel.value, precision);
  const fromU = f.units.find((u) => u.key === fromSel.value);
  const toU = f.units.find((u) => u.key === toSel.value);

  resultEl.textContent = `${val} ${pretty(fromU.label)}  =  ${out} ${pretty(toU.label)}`;

  formulaEl.textContent =
    f.field === 'temperature'
      ? 'temperature: special-cased (Celsius pivot), not via nm'
      : `value × (to.nm / from.nm) = ${val} × (${toU.nm} / ${fromU.nm})`;
}

function refreshUnits() {
  const f = currentField();
  fillUnits(fromSel, f.units, 0);
  fillUnits(toSel, f.units, Math.min(1, f.units.length - 1));
  compute();
}

// Populate the field dropdown (sorted by label; copy so we don't mutate data)
[...fields].sort(byLabel).forEach((f) => {
  const o = document.createElement('option');
  o.value = f.field;
  o.textContent = f.label;
  fieldSel.appendChild(o);
});

fieldSel.addEventListener('change', refreshUnits);
[fromSel, toSel, valInput, precInput].forEach((el) =>
  el.addEventListener('input', compute)
);
$('swap').addEventListener('click', () => {
  [fromSel.value, toSel.value] = [toSel.value, fromSel.value];
  compute();
});

// Init
fieldSel.selectedIndex = 0;
refreshUnits();
