import packageJson from '@root/package.json';
import { genUnitsSystem, convertTemperature } from '@src/convert';

export function getVersion() {
  return packageJson.version;
}

export function genUnits(field, options = {}) {
  return (
    (genUnitsSystem(options).find((u) => u.field === field) || {}).units || []
  );
}

export function genUnit(field, key, options = {}) {
  const units = genUnits(field, options);
  return units.find((u) => u.key === key) || {};
}

export function reUnit(optionLayers, options = {}) {
  const uniFields = genUnitsSystem(options);
  const uniObj = uniFields.find((field) => field.field === optionLayers);
  const defaultUnit = uniObj?.field || '';
  const preUnit = uniFields.length > 0 ? uniFields[0].field : '';
  return defaultUnit === '' ? preUnit : defaultUnit;
}

export function unitConversion(field, key, val, options = {}, precision = 5) {
  if (typeof val === 'undefined' || val == null || val === '') {
    return val;
  }
  if (val === 0) {
    if (field !== 'temperature') return val;
  }
  if (field === 'temperature') return convertTemperature(key, val);

  const units = genUnits(field, options);
  if (units.length <= 1) return val;

  const idx = units.findIndex((u) => u.key === key);
  if (idx === -1) return val;

  const prevIdx = idx === 0 ? units.length - 1 : idx - 1;
  const prevUnit = units[prevIdx];
  const targetUnitObj = units[idx];

  // Handle unit conversions with unit_type restrictions (specific_current, electrical_potential, etc.)
  // If both units have unit_type defined, check if they're compatible
  if (
    targetUnitObj.unit_type &&
    prevUnit.unit_type &&
    targetUnitObj.unit_type !== prevUnit.unit_type
  ) {
    return val;
  }

  return parseFloat(
    (parseFloat(val) * (targetUnitObj.nm / prevUnit.nm)).toFixed(precision)
  );
}
